if (server.aof_use_rdb_preamble) {
    int error;
    /* Persist the replication ID / offset in the RDB preamble of the base
     * file, so the rewritten AOF keeps the replication identity of this
     * instance. rdbSaveInfoAuxFields() only emits the repl-id and
     * repl-offset aux fields when it gets a non-NULL rsi. */
    rdbSaveInfo rsi, *rsiptr;
    rsiptr = rdbPopulateSaveInfo(&rsi);
    if (rsiptr == NULL) {
        /* No replication stream info available (e.g. a master that has no
         * backlog yet). The selected DB of the replication stream is
         * irrelevant for an AOF base, since the AOF tail that follows it
         * always starts with its own SELECT, so just record db 0 and keep
         * the replication ID / offset. */
        rsi.repl_stream_db = 0;
        rsiptr = &rsi;
